CREATE FUNCTION public.payroll_override_batch(t uuid,changes jsonb,repeating boolean,rev integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;n integer:=rev;pid uuid;y integer;m integer;first_y integer;first_m integer;BEGIN
IF NOT public.payroll_manager(t,auth.uid()) OR jsonb_typeof(changes)<>'array' OR jsonb_array_length(changes) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Invalid payroll proposal';END IF;
FOR c IN SELECT value FROM jsonb_array_elements(changes) LOOP pid:=(c->>'payroll_id')::uuid;SELECT year,month INTO y,m FROM public.hr_payroll WHERE id=pid AND tenant_id=t;IF y IS NULL THEN RAISE EXCEPTION 'Person payroll not found';END IF;IF first_y IS NULL THEN first_y:=y;first_m:=m;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));ELSIF (first_y,first_m) IS DISTINCT FROM (y,m) THEN RAISE EXCEPTION 'Changes must belong to one month';END IF;
PERFORM public.payroll_override(t,pid,c->>'field',(c->>'value')::numeric,(c->>'previous')::numeric,c->>'reason',repeating,n);n:=n+1;END LOOP;END $$;
REVOKE ALL ON FUNCTION public.payroll_override_batch(uuid,jsonb,boolean,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_override_batch(uuid,jsonb,boolean,integer) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.payroll_prepare(uuid,integer,integer)'::regprocedure) INTO def;def:=replace(def,'prepared_by=EXCLUDED.prepared_by','prepared_by=COALESCE(hr_payroll_months.prepared_by,EXCLUDED.prepared_by)');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_approve(uuid,integer,integer,integer)'::regprocedure) INTO def;def:=replace(def,'IF s->>''approvals''=''strict'' AND period.prepared_by=auth.uid()','IF s->>''approvals''=''strict'' AND (period.prepared_by=auth.uid() OR EXISTS(SELECT 1 FROM public.hr_payroll_overrides a JOIN public.hr_payroll ap ON ap.id=a.payroll_id AND ap.tenant_id=t WHERE a.tenant_id=t AND ap.year=y AND ap.month=m AND a.created_by=auth.uid()))');def:=replace(def,'rows:=public.payroll_preview(t,y,m);','IF EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.tenant_id=t AND e.hire_date<=(make_date(y,m,1)+interval ''1 month -1 day'')::date AND (e.end_date IS NULL AND e.status IN (''active'',''on_leave'') OR e.end_date>=make_date(y,m,1)) AND NOT public.people_person_access(t,e.id,auth.uid())) THEN RAISE EXCEPTION ''Whole-month approval requires access to every person'';END IF; rows:=public.payroll_preview(t,y,m);');EXECUTE def;END $$;
CREATE FUNCTION public.payroll_snapshot_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Payroll audit and payslip records are immutable';END $$;
CREATE TRIGGER payslip_immutable BEFORE UPDATE OR DELETE ON public.hr_payslips FOR EACH ROW EXECUTE FUNCTION public.payroll_snapshot_immutable();
CREATE TRIGGER payroll_override_immutable BEFORE UPDATE OR DELETE ON public.hr_payroll_overrides FOR EACH ROW EXECUTE FUNCTION public.payroll_snapshot_immutable();